"use client";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type PointerEvent,
} from "react";
import {
  SectionImage,
  sectionStyles,
  useSectionEnvironment,
  useSectionLoop,
  useSectionSelection,
} from "./section-shared";
import { sectionClamp, sectionWrap } from "./section-math";
export interface DriftGalleryItem {
  id: string;
  title: string;
  src?: string;
  alt?: string;
  description?: string;
  category?: string;
  content?: ReactNode;
}
export interface DriftGalleryProps {
  items: readonly DriftGalleryItem[];
  title?: ReactNode;
  description?: ReactNode;
  watermark?: string;
  action?: { label: string; href: string };
  index?: number;
  defaultIndex?: number;
  onChange?: (index: number) => void;
  onSelect?: (item: DriftGalleryItem) => void;
  drag?: boolean;
  autoplay?: boolean;
  speed?: number;
  cardWidth?: number;
  gap?: number;
  separation?: number;
  friction?: number;
  height?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}
/** Lateral inertial product cards with grab separation and velocity-driven grain/color. */
export function DriftGallery({
  items,
  title = "Made for the move.",
  description,
  watermark = "FIELD 26",
  action,
  index,
  defaultIndex = 0,
  onChange,
  onSelect,
  drag = true,
  autoplay = false,
  speed = 0.12,
  cardWidth = 250,
  gap = 35,
  separation = 45,
  friction = 4.5,
  height = 720,
  className = "",
  style,
  label = "Drift gallery",
}: DriftGalleryProps) {
  const env = useSectionEnvironment(),
    selection = useSectionSelection(
      items.length,
      index,
      defaultIndex,
      onChange,
    ),
    [phase, setPhase] = useState(defaultIndex),
    [velocity, setVelocity] = useState(0),
    [grabbed, setGrabbed] = useState(false),
    motion = useRef({
      phase: defaultIndex,
      velocity: 0,
      target: null as number | null,
    }),
    pointer = useRef<null | {
      id: number;
      x: number;
      time: number;
      distance: number;
    }>(null),
    noise = useId().replaceAll(":", "");
  const width = Math.min(cardWidth, env.size.width * 0.55),
    step = width + Math.max(0, gap),
    spread = grabbed ? Math.max(0, separation) : 0;
  const publish = () => {
    setPhase(motion.current.phase);
    setVelocity(motion.current.velocity);
    selection.select(Math.round(motion.current.phase));
  };
  useEffect(() => {
    if (index !== undefined) {
      motion.current.phase = index;
      motion.current.velocity = 0;
      setPhase(index);
    }
  }, [index]);
  useSectionLoop(env.active && !env.reduced, (delta) => {
    const m = motion.current;
    if (pointer.current) return;
    if (m.target !== null) {
      m.phase += (m.target - m.phase) * (1 - Math.exp(-delta * 9));
      if (Math.abs(m.target - m.phase) < 0.0005) {
        m.phase = m.target;
        m.target = null;
      }
    } else {
      if (Math.abs(m.velocity) < 0.002 && !autoplay) return;
      m.phase += (m.velocity + (autoplay ? speed : 0)) * delta;
      m.velocity *= Math.exp(-Math.max(0.5, friction) * delta);
    }
    publish();
  });
  const go = (next: number) => {
    const m = motion.current;
    m.velocity = 0;
    if (env.reduced) {
      m.phase = next;
      publish();
    } else m.target = next;
    selection.select(next);
  };
  const end = (event: PointerEvent<HTMLDivElement>) => {
    if (pointer.current?.id !== event.pointerId) return;
    pointer.current = null;
    setGrabbed(false);
    if (env.reduced) {
      motion.current.velocity = 0;
      setVelocity(0);
    }
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  };
  const chosen = items[selection.selected];
  return (
    <div
      ref={env.ref}
      role="region"
      aria-label={label}
      tabIndex={0}
      className={`z-as z-as-drift ${className}`}
      data-section="drift-gallery"
      data-index={selection.selected}
      data-phase={phase.toFixed(5)}
      data-velocity={velocity.toFixed(4)}
      data-grabbed={grabbed}
      data-separation={spread}
      style={{ height: `min(${height}px,100svh)`, minHeight: 540, ...style }}
      onKeyDown={(e) => {
        if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
          e.preventDefault();
          go(
            Math.round(motion.current.phase) +
              (e.key === "ArrowRight" ? 1 : -1),
          );
        }
      }}
      onPointerDown={(event) => {
        if (
          !drag ||
          event.button !== 0 ||
          (event.target as HTMLElement).closest("nav, a, .z-as-drift-intro")
        )
          return;
        pointer.current = {
          id: event.pointerId,
          x: event.clientX,
          time: event.timeStamp,
          distance: 0,
        };
        motion.current.velocity = 0;
        motion.current.target = null;
        setGrabbed(true);
        event.currentTarget.setPointerCapture?.(event.pointerId);
      }}
      onPointerMove={(event) => {
        const p = pointer.current;
        if (!p || p.id !== event.pointerId) return;
        const delta = (p.x - event.clientX) / step,
          dt = Math.max(0.008, (event.timeStamp - p.time) / 1000);
        motion.current.phase += delta;
        motion.current.velocity = sectionClamp(delta / dt, -8, 8);
        pointer.current = {
          id: p.id,
          x: event.clientX,
          time: event.timeStamp,
          distance: p.distance + Math.abs(delta),
        };
        publish();
      }}
      onPointerUp={end}
      onPointerCancel={(event) => {
        motion.current.velocity = 0;
        end(event);
      }}
      onLostPointerCapture={() => {
        pointer.current = null;
        setGrabbed(false);
      }}
    >
      <style>
        {sectionStyles +
          `.z-as-drift{overflow:hidden;touch-action:pan-y;user-select:none;cursor:grab}.z-as-drift[data-grabbed=true]{cursor:grabbing}.z-as-drift .z-as-drift-intro{position:absolute;top:30px;left:4.4%;z-index:5;max-width:470px;cursor:auto}.z-as-drift .z-as-drift-intro h2{font-size:clamp(32px,5.4vw,64px);line-height:1.05;letter-spacing:-.05em;font-weight:600}.z-as-drift .z-as-drift-intro p{font-size:13px;color:#777;max-width:290px;margin:20px 0}.z-as-drift .z-as-drift-intro a{display:inline-block;background:var(--z-as-accent);color:#171717;border-radius:40px;text-decoration:none;font-size:11px;letter-spacing:.06em;text-transform:uppercase;padding:12px 22px}.z-as-drift .z-as-drift-watermark{position:absolute;top:30%;left:-2%;font-size:clamp(100px,34vw,440px);letter-spacing:-.07em;font-weight:600;line-height:1;white-space:nowrap;color:#11111108;pointer-events:none}.z-as-drift .z-as-drift-card{position:absolute;left:50%;top:46%;height:36%;min-height:180px;max-height:330px;will-change:transform;border:0;padding:0;background:#d7d7d2;border-radius:8px;overflow:hidden;cursor:inherit;transition:filter .15s}.z-as-drift .z-as-drift-card>span{position:absolute;bottom:0;left:0;right:0;padding:24px 15px 12px;background:linear-gradient(transparent,#0008);color:white;text-align:left;font-size:14px}.z-as-drift .z-as-drift-detail{position:absolute;top:36px;right:4.4%;max-width:180px;text-align:right;z-index:3;font-size:12px}.z-as-drift .z-as-drift-detail strong{display:block;font-size:22px;font-weight:400;letter-spacing:-.03em}.z-as-drift .z-as-drift-detail small{color:#999}.z-as-drift .z-as-controls{position:absolute;bottom:24px;left:0;right:0;z-index:6}.z-as-drift .z-as-controls button{background:#1111}.z-as-drift .z-as-controls span{font-size:12px}@media(max-width:600px){.z-as-drift .z-as-drift-intro{top:25px;right:20px}.z-as-drift .z-as-drift-intro p{margin:12px 0}.z-as-drift .z-as-drift-detail{display:none}.z-as-drift .z-as-drift-card{top:47%;height:35%;min-height:160px}.z-as-drift .z-as-drift-watermark{top:40%;font-size:38vw}}`}
      </style>
      <div className="z-as-drift-intro">
        <h2>{title}</h2>
        <p>{description}</p>
        {action && <a href={action.href}>{action.label}</a>}
      </div>
      <div className="z-as-drift-watermark" aria-hidden="true">
        {watermark}
      </div>
      {chosen && (
        <div className="z-as-drift-detail">
          <small>{String(selection.selected + 1).padStart(2, "0")}</small>
          <strong>{chosen.title}</strong>
          <span>{chosen.category}</span>
        </div>
      )}
      {items.map((item, i) => {
        const distance =
            sectionWrap(i - phase + items.length / 2, items.length) -
            items.length / 2,
          x = distance * step + Math.sign(distance) * spread,
          y = Math.sin(distance * 0.9) * 12;
        return (
          <button
            key={item.id}
            type="button"
            aria-label={`View ${item.title}`}
            className="z-as-drift-card"
            data-drift-card={i}
            style={{
              width,
              transform: `translate3d(calc(-50% + ${x}px),${y}px,0) rotate(${sectionClamp(velocity * distance * 0.35, -8, 8)}deg)`,
              filter: `saturate(${1 + Math.min(1.2, Math.abs(velocity) * 0.14)})`,
              transition:
                grabbed && !env.reduced ? "transform .16s ease-out" : "none",
            }}
            onClick={() => {
              if (Math.abs(velocity) < 0.3) {
                go(i);
                onSelect?.(item);
              }
            }}
          >
            <SectionImage item={item} />
            <span>{item.title}</span>
          </button>
        );
      })}
      <svg
        className="z-as-fill"
        aria-hidden="true"
        style={{
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          opacity: Math.min(0.22, Math.abs(velocity) * 0.045),
          mixBlendMode: "multiply",
          zIndex: 4,
        }}
      >
        <filter id={noise}>
          <feTurbulence
            type="fractalNoise"
            baseFrequency=".65"
            numOctaves="3"
            stitchTiles="stitch"
          />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${noise})`} />
      </svg>
      <nav className="z-as-controls" aria-label="Gallery navigation">
        <button
          type="button"
          aria-label="Previous product"
          onClick={() => go(Math.round(motion.current.phase) - 1)}
        >
          ‹
        </button>
        <span aria-live="polite">{chosen?.title ?? "No products"}</span>
        <button
          type="button"
          aria-label="Next product"
          onClick={() => go(Math.round(motion.current.phase) + 1)}
        >
          ›
        </button>
      </nav>
    </div>
  );
}

// @zeus-internal
export const sectionClamp = (value: number, min = 0, max = 1) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : 0));
export const sectionWrap = (value: number, count: number) =>
  count > 0 ? ((value % count) + count) % count : 0;
export type SectionPoint = readonly [number, number, number];
export function spherePoint(latitude: number, longitude: number): SectionPoint {
  const lat = (latitude * Math.PI) / 180,
    lon = (longitude * Math.PI) / 180;
  return [
    Math.cos(lat) * Math.sin(lon),
    -Math.sin(lat),
    Math.cos(lat) * Math.cos(lon),
  ];
}
export function rotatePoint(
  [x, y, z]: SectionPoint,
  yaw: number,
  pitch: number,
): SectionPoint {
  const xx = x * Math.cos(yaw) + z * Math.sin(yaw),
    zz = z * Math.cos(yaw) - x * Math.sin(yaw);
  return [
    xx,
    y * Math.cos(pitch) - zz * Math.sin(pitch),
    zz * Math.cos(pitch) + y * Math.sin(pitch),
  ];
}
export function fibonacciPoint(index: number, count: number): SectionPoint {
  const y = 1 - (2 * (index + 0.5)) / Math.max(1, count),
    r = Math.sqrt(1 - y * y),
    angle = index * Math.PI * (3 - Math.sqrt(5));
  return [Math.cos(angle) * r, y, Math.sin(angle) * r];
}

// @zeus-internal
"use client";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  type PointerEvent,
} from "react";
import { sectionClamp, sectionWrap } from "./section-math";
export interface SectionInternalMedia {
  src?: string;
  alt?: string;
  content?: ReactNode;
}
export interface SectionInternalItem extends SectionInternalMedia {
  id: string;
  title: string;
  description?: string;
}
export interface SectionInternalBase {
  className?: string;
  style?: CSSProperties;
  height?: number;
  label?: string;
}
export interface SectionInternalLink {
  label: string;
  href: string;
}
export interface SectionInternalGroup {
  title: string;
  links: readonly SectionInternalLink[];
}
export function useSectionEnvironment() {
  const ref = useRef<HTMLDivElement>(null),
    [size, setSize] = useState({ width: 1000, height: 640 }),
    [active, setActive] = useState(false),
    [reduced, setReduced] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    let visible = true;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      setActive(visible && !document.hidden);
      setReduced(media.matches);
    };
    const resize = () =>
      setSize({
        width: node.clientWidth || 1000,
        height: node.clientHeight || 640,
      });
    const ro =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize);
    ro?.observe(node);
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver((entries) => {
            visible = entries[0]?.isIntersecting ?? true;
            update();
          });
    io?.observe(node);
    media.addEventListener("change", update);
    document.addEventListener("visibilitychange", update);
    resize();
    update();
    return () => {
      ro?.disconnect();
      io?.disconnect();
      media.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", update);
    };
  }, []);
  return { ref, size, active, reduced };
}
export function useSectionLoop(
  active: boolean,
  callback: (delta: number) => void,
) {
  const latest = useRef(callback);
  latest.current = callback;
  useEffect(() => {
    if (!active) return;
    let frame = 0,
      last = 0;
    const tick = (now: number) => {
      const delta = last ? Math.min(0.04, (now - last) / 1000) : 0;
      last = now;
      latest.current(delta);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active]);
}
export function useSectionSelection(
  count: number,
  index: number | undefined,
  defaultIndex: number,
  onChange?: (index: number) => void,
) {
  const [local, setLocal] = useState(defaultIndex);
  const selected = sectionWrap(Math.round(index ?? local), count),
    current = useRef(selected);
  current.current = selected;
  const select = useCallback(
    (next: number) => {
      next = sectionWrap(Math.round(next), count);
      if (next === current.current) return;
      if (index === undefined) {
        current.current = next;
        setLocal(next);
      }
      onChange?.(next);
    },
    [count, index, onChange],
  );
  return { selected, select, current };
}
export function useSectionScroll(
  ref: RefObject<HTMLElement | null>,
  scrollContainer?: RefObject<HTMLElement | null>,
  onProgress?: (progress: number) => void,
) {
  const [progress, setProgress] = useState(0),
    latest = useRef(onProgress),
    previous = useRef(-1);
  latest.current = onProgress;
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    let frame = 0;
    const container = scrollContainer?.current;
    const measure = () => {
      frame = 0;
      const box = node.getBoundingClientRect(),
        top = container?.getBoundingClientRect().top ?? 0,
        view = container?.clientHeight ?? innerHeight;
      const next = sectionClamp(
        (top - box.top) / Math.max(1, box.height - view),
      );
      if (Math.abs(previous.current - next) >= 0.0001) {
        previous.current = next;
        setProgress(next);
        latest.current?.(next);
      }
    };
    const request = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    const target = container ?? window;
    target.addEventListener("scroll", request, { passive: true });
    window.addEventListener("resize", request);
    const ro =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(request);
    ro?.observe(node);
    measure();
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", request);
      window.removeEventListener("resize", request);
      ro?.disconnect();
    };
  }, [ref, scrollContainer]);
  return progress;
}
export function useSphereRotation(
  active: boolean,
  reduced: boolean,
  autoplay: boolean,
  speed: number,
  drag: boolean,
) {
  const state = useRef({
      yaw: 0,
      pitch: 0,
      vx: 0,
      vy: 0,
      target: null as null | { yaw: number; pitch: number },
    }),
    [rotation, setRotation] = useState({ yaw: 0, pitch: 0 }),
    pointer = useRef<null | { id: number; x: number; y: number; time: number }>(
      null,
    );
  const publish = () =>
    setRotation({ yaw: state.current.yaw, pitch: state.current.pitch });
  useSectionLoop(active && !reduced, (delta) => {
    const s = state.current;
    if (pointer.current) return;
    if (s.target) {
      const ease = 1 - Math.exp(-delta * 6);
      s.yaw += (s.target.yaw - s.yaw) * ease;
      s.pitch += (s.target.pitch - s.pitch) * ease;
      if (
        Math.abs(s.yaw - s.target.yaw) + Math.abs(s.pitch - s.target.pitch) <
        0.001
      )
        s.target = null;
    } else {
      s.yaw += (s.vx + (autoplay ? speed : 0)) * delta;
      s.pitch = sectionClamp(s.pitch + s.vy * delta, -1.2, 1.2);
      s.vx *= Math.exp(-delta * 5);
      s.vy *= Math.exp(-delta * 5);
    }
    publish();
  });
  const orient = useCallback(
    (yaw: number, pitch: number) => {
      const s = state.current;
      const shortest =
        ((((yaw - s.yaw + Math.PI) % (Math.PI * 2)) + Math.PI * 2) %
          (Math.PI * 2)) -
        Math.PI;
      s.vx = 0;
      s.vy = 0;
      if (reduced) {
        s.yaw += shortest;
        s.pitch = pitch;
        s.target = null;
        setRotation({ yaw: s.yaw, pitch: s.pitch });
      } else s.target = { yaw: s.yaw + shortest, pitch };
    },
    [reduced],
  );
  const end = (event: PointerEvent<HTMLElement>) => {
    if (pointer.current?.id !== event.pointerId) return;
    pointer.current = null;
    if (reduced) {
      state.current.vx = 0;
      state.current.vy = 0;
    }
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  };
  return {
    rotation,
    orient,
    handlers: {
      onPointerDown: (event: PointerEvent<HTMLElement>) => {
        if (
          !drag ||
          event.button !== 0 ||
          (event.target as HTMLElement).closest("button,a,input")
        )
          return;
        pointer.current = {
          id: event.pointerId,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        state.current.target = null;
        state.current.vx = state.current.vy = 0;
        event.currentTarget.setPointerCapture?.(event.pointerId);
      },
      onPointerMove: (event: PointerEvent<HTMLElement>) => {
        const p = pointer.current;
        if (!p || p.id !== event.pointerId) return;
        const dx = (event.clientX - p.x) * 0.006,
          dy = (event.clientY - p.y) * 0.006,
          dt = Math.max(0.008, (event.timeStamp - p.time) / 1000);
        state.current.yaw += dx;
        state.current.pitch = sectionClamp(state.current.pitch + dy, -1.2, 1.2);
        state.current.vx = sectionClamp(dx / dt, -5, 5);
        state.current.vy = sectionClamp(dy / dt, -3, 3);
        pointer.current = {
          id: p.id,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        publish();
      },
      onPointerUp: end,
      onPointerCancel: end,
      onLostPointerCapture: () => {
        pointer.current = null;
      },
    },
  };
}
export function SectionImage({
  item,
  className,
  style,
}: {
  item: SectionInternalMedia;
  className?: string;
  style?: CSSProperties;
}) {
  return item.content ? (
    <div className={className} style={style}>
      {item.content}
    </div>
  ) : item.src ? (
    <img
      className={className}
      style={style}
      src={item.src}
      alt={item.alt ?? ""}
      draggable={false}
    />
  ) : (
    <div className={className} style={style} />
